import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const g=JSON.parse('{"title":"点数怎么计算","description":"","frontmatter":{"title":"点数怎么计算"},"headers":[],"relativePath":"billing/points.md","filePath":"billing/points.md","lastUpdated":1787949005000}'),i={name:"billing/points.md"};function l(n,t,s,d,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="点数怎么计算" tabindex="-1">点数怎么计算 <a class="header-anchor" href="#点数怎么计算" aria-label="Permalink to &quot;点数怎么计算&quot;">​</a></h1><p>点数是熠智 AI 的使用量单位。这一页讲点数从哪来、往哪去、去哪查。</p><h2 id="点数从哪来" tabindex="-1">点数从哪来 <a class="header-anchor" href="#点数从哪来" aria-label="Permalink to &quot;点数从哪来&quot;">​</a></h2><ul><li><strong>套餐额度</strong>：订阅套餐每个 30 天周期发放客服接待点数，周期结束清零、不结转。</li><li><strong>加油包</strong>：一次性购买的客服接待点数包，套餐额度用完后自动消耗。部分有有效期，部分永久有效。加油包不含运营助手额度。</li><li><strong>兑换码</strong>：兑换后按码面内容到账，见<a href="/aicare-docs/billing/redeem">兑换码</a>。</li></ul><p>扣减顺序：先扣套餐周期额度，再扣加油包。</p><h2 id="点数往哪去" tabindex="-1">点数往哪去 <a class="header-anchor" href="#点数往哪去" aria-label="Permalink to &quot;点数往哪去&quot;">​</a></h2><p>会消耗点数的动作，和账单消耗记录里的名称一致：</p><table tabindex="0"><thead><tr><th>动作</th><th>什么时候发生</th></tr></thead><tbody><tr><td>AI 客服回复</td><td>AI 完成一次顾客回复，单次消耗并非固定值</td></tr><tr><td>商品学习整理</td><td>每生成一份整理后的商品资料</td></tr><tr><td>整理回答内容</td><td>知识内容入库时的处理</td></tr><tr><td>挑选回答依据</td><td>回答时筛选参考资料</td></tr></tbody></table><p>AI 每次回复会消耗点数，单次消耗不是固定值。每个动作实际扣了多少，以客户端或网页工作台「账单」里的<strong>消耗记录</strong>为准。</p><h2 id="运营助手额度" tabindex="-1">运营助手额度 <a class="header-anchor" href="#运营助手额度" aria-label="Permalink to &quot;运营助手额度&quot;">​</a></h2><p>运营助手使用单独的月度额度，不和客服接待点数混用。它按自然月累计，每月 1 日重置，不按 30 天滚动。</p><p>普通点数加油包只补充客服接待点数，不包含运营助手。运营助手是否开放、当月额度多少，以「账单」页当前套餐说明和运营助手页面显示为准。</p><h2 id="去哪查" tabindex="-1">去哪查 <a class="header-anchor" href="#去哪查" aria-label="Permalink to &quot;去哪查&quot;">​</a></h2><p>客户端左侧菜单「账单」（或网页工作台「账单」标签页）：</p><ul><li>顶部是<strong>当前可用点数</strong>和套餐额度。</li><li><strong>消耗记录</strong>按动作类型和日期展开，能看到每天每类动作用了多少。</li></ul><h2 id="控制消耗的办法" tabindex="-1">控制消耗的办法 <a class="header-anchor" href="#控制消耗的办法" aria-label="Permalink to &quot;控制消耗的办法&quot;">​</a></h2><ol><li><strong>智能程度别一步到位</strong>。日常用「适中」，只给高价值场景开「高级」以上。</li><li><strong>固定答案走关键词回复</strong>。<a href="/aicare-docs/solution/keywords">关键词回复</a>直接发话术，不消耗 AI 回复点数。</li><li><strong>商品学习整理分批做</strong>。先小批量整理看效果，再决定是否全量。</li><li><strong>每周看一次消耗记录</strong>。异常放大时先查是哪类动作，再对症调整。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>点数用完了会怎样？</strong> 可用点数不足时 AI 接待会受影响。及时购买加油包或续费套餐，见<a href="/aicare-docs/billing/purchase">购买套餐和加油包</a>。</p><p><strong>测试对话消耗点数吗？</strong> 方案编辑器里的对话测试会标记为测试，不扣客服回复点数。</p>',20)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
